keyConcepts.codeExample:
interface PaymentMethod {
  token: string;
  amount: number;
}

interface RefundRequest {
  token: string;
  amount: number;
}

function charge(payment: PaymentMethod): void {
  console.log(`Charging ${payment.amount} with token ${payment.token}`);
}

const refund: RefundRequest = { token: 'tok_123', amount: 42 };

// Compile sans erreur : les deux types ont la même forme,
// mais un remboursement n'est pas un paiement.
charge(refund);

// Fix : ajouter un discriminant littéral pour empêcher la confusion.
interface SafePaymentMethod {
  kind: 'payment';
  token: string;
  amount: number;
}

